import React, { useState, useEffect, useRef } from 'react';
import { Card, Button, Alert, api } from '../App';

const MAX_SLOTS = 5;

// ── Multi-select column filter dropdown ──────────────────────────────────────
const ColFilter = ({ label, options, selected, onChange }) => {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    const handler = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const toggle = (v) => onChange(selected.includes(v) ? selected.filter(x => x !== v) : [...selected, v]);

  return (
    <div ref={ref} style={{ position: 'relative', display: 'inline-block' }}>
      <div onClick={() => setOpen(o => !o)}
        style={{ cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 4, userSelect: 'none', whiteSpace: 'nowrap' }}>
        <span>{label}</span>
        {selected.length > 0
          ? <span style={{ background: '#f59e0b', color: '#fff', borderRadius: 99, fontSize: 10, padding: '1px 5px', fontWeight: 700 }}>{selected.length}</span>
          : <span style={{ fontSize: 9, opacity: 0.6 }}>▼</span>
        }
      </div>
      {open && (
        <div style={{ position: 'absolute', top: '110%', left: 0, background: '#fff', border: '1px solid #e2e8f0',
          borderRadius: 8, zIndex: 200, boxShadow: '0 8px 24px rgba(0,0,0,0.15)', minWidth: 180, maxHeight: 260, overflowY: 'auto' }}>
          <div style={{ padding: '8px 12px', borderBottom: '1px solid #f0f4f8', display: 'flex', justifyContent: 'space-between', alignItems: 'center', position: 'sticky', top: 0, background: '#fff' }}>
            <span style={{ fontSize: 11, color: '#888', fontWeight: 700 }}>Filter {label}</span>
            <button onMouseDown={() => onChange([])}
              style={{ border: 'none', background: 'none', cursor: 'pointer', fontSize: 11, color: '#c0392b', fontWeight: 700 }}>Clear all</button>
          </div>
          {options.length === 0
            ? <div style={{ padding: '12px', fontSize: 12, color: '#aaa', textAlign: 'center' }}>No options</div>
            : options.map(opt => (
              <div key={opt} onMouseDown={() => toggle(opt)}
                style={{ padding: '8px 12px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 8,
                  background: selected.includes(opt) ? '#eff6ff' : '#fff', fontSize: 13, color: '#1a2533',
                  borderBottom: '1px solid #f9fafb' }}>
                <div style={{ width: 16, height: 16, borderRadius: 3, flexShrink: 0,
                  border: `2px solid ${selected.includes(opt) ? '#1a3c5e' : '#cbd5e0'}`,
                  background: selected.includes(opt) ? '#1a3c5e' : '#fff',
                  display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  {selected.includes(opt) && <span style={{ color: '#fff', fontSize: 10, fontWeight: 700 }}>✓</span>}
                </div>
                <span style={{ fontWeight: selected.includes(opt) ? 700 : 400 }}>{opt}</span>
              </div>
            ))
          }
        </div>
      )}
    </div>
  );
};

// ── Main component ───────────────────────────────────────────────────────────
export default function MarkingPage() {
  const [allParties,  setAllParties]  = useState([]);
  const [saleNos,     setSaleNos]     = useState([]);
  const [selParties,  setSelParties]  = useState([]);
  const [saleNo,      setSaleNo]      = useState('');
  const [partySearch, setPartySearch] = useState('');

  const [preview,      setPreview]      = useState([]); // lots with party_slots_array
  const [partyOrder,   setPartyOrder]   = useState([]);
  const [prices,       setPrices]       = useState({});
  const [skipRows,     setSkipRows]     = useState({});
  // Extra parties per lot: catalogue_id -> [{party_id, party_name, party_code}]
  const [extraParties, setExtraParties] = useState({});
  const [addInputs,    setAddInputs]    = useState({});
  const [notifications,setNotifications]= useState({}); // catalogue_id -> message
  const [loading,      setLoading]      = useState(false);
  const [saving,       setSaving]       = useState(false);
  const [alert,        setAlert]        = useState(null);

  // Column filters
  const [filterGrades,  setFilterGrades]  = useState([]);
  const [filterGardens, setFilterGardens] = useState([]);
  const [filterBrokers, setFilterBrokers] = useState([]);
  const [searchLot,     setSearchLot]     = useState('');

  useEffect(() => {
    Promise.all([
      api.get('/parties').catch(() => ({ data: [] })),
      api.get('/import/sale-numbers').catch(() => ({ data: [] }))
    ]).then(([p, s]) => { setAllParties(p.data); setSaleNos(s.data); });
  }, []);

  const toggleParty = (p) =>
    setSelParties(prev => prev.find(x => x.id === p.id)
      ? prev.filter(x => x.id !== p.id)
      : [...prev, { id: p.id, party_name: p.party_name, party_code: p.party_code }]
    );

  const filteredParties = allParties.filter(p =>
    p.party_name.toLowerCase().includes(partySearch.toLowerCase()) ||
    p.party_code.toLowerCase().includes(partySearch.toLowerCase())
  );

  const selectAll   = () => setSelParties(filteredParties.map(p => ({ id: p.id, party_name: p.party_name, party_code: p.party_code })));
  const deselectAll = () => setSelParties([]);

  const runPreview = async () => {
    if (!selParties.length || !saleNo) { setAlert({ msg: 'Select at least one party and sale number', type: 'error' }); return; }
    setLoading(true); setAlert(null); setNotifications({});
    setFilterGrades([]); setFilterGardens([]); setFilterBrokers([]); setSearchLot('');
    try {
      const r = await api.post('/marking/preview', { party_ids: selParties.map(p => p.id), sale_no: saleNo });
      setPreview(r.data.lots || []);
      setPartyOrder(r.data.parties || []);
      const init = {};
      (r.data.lots || []).forEach(row => { init[row.catalogue_id] = row.suggested_price || ''; });
      setPrices(init); setSkipRows({}); setExtraParties({}); setAddInputs({});
      if (!r.data.lots?.length)
        setAlert({ msg: 'No lots found. Check Party Master — ensure grades have Max Lots > 0 and gardens are mapped.', type: 'warning' });
    } catch (e) { setAlert({ msg: e.response?.data?.error || e.message, type: 'error' }); }
    finally { setLoading(false); }
  };

  const getCodeSuggestions = (val) => {
    if (!val || val.length < 1) return [];
    return allParties.filter(p => p.party_code.startsWith(val.toUpperCase())).slice(0, 6);
  };

  // Add party manually to a lot — fills next available compact slot
  const addExtraParty = async (catalogueId) => {
    const code = (addInputs[catalogueId] || '').trim().toUpperCase();
    if (!code) return;
    const p = allParties.find(x => x.party_code === code);
    if (!p) { setNotifications(prev => ({ ...prev, [catalogueId]: { type: 'error', msg: `Party code "${code}" not found` } })); return; }

    const lot = preview.find(x => x.catalogue_id === catalogueId);
    const mainSlots  = lot?.party_slots_array || [];
    const extraSlots = extraParties[catalogueId] || [];

    // Check if already in main or extra
    const alreadyIn = [...mainSlots, ...extraSlots].find(x => x.party_code === code);
    if (alreadyIn) {
      setNotifications(prev => ({ ...prev, [catalogueId]: { type: 'warn', msg: `${code} already assigned to this lot` } }));
      return;
    }

    // Check total slots
    if (mainSlots.length + extraSlots.length >= MAX_SLOTS) {
      setNotifications(prev => ({ ...prev, [catalogueId]: { type: 'error', msg: `Max ${MAX_SLOTS} parties per lot reached` } }));
      return;
    }

    // Check BGG duplicate — notify but allow
    try {
      const r = await api.post('/marking/check-bgg', {
        party_id: p.id, sale_no: saleNo,
        broker: lot?.broker, garden: lot?.garden, grade: lot?.grade
      });
      if (r.data.exists) {
        const existingLots = r.data.existing_lots.map(l => l.lot_no || '?').join(', ');
        setNotifications(prev => ({
          ...prev,
          [catalogueId]: {
            type: 'warn',
            msg: `⚠️ ${code} already marked for ${lot?.garden}/${lot?.grade} (Lot: ${existingLots}). Added anyway.`
          }
        }));
        // Still add — just warn
      } else {
        setNotifications(prev => { const n = {...prev}; delete n[catalogueId]; return n; });
      }
    } catch (e) { /* allow adding even if check fails */ }

    setExtraParties(prev => ({
      ...prev,
      [catalogueId]: [...(prev[catalogueId] || []), { party_id: p.id, party_name: p.party_name, party_code: code }]
    }));
    setAddInputs(prev => ({ ...prev, [catalogueId]: '' }));
  };

  const handleAddKeyDown = (e, catalogueId) => {
    if (e.key === 'Enter') { e.preventDefault(); addExtraParty(catalogueId); }
  };

  const save = async () => {
    const markings = preview.filter(r => !skipRows[r.catalogue_id]).map(row => ({
      ...row,
      party_slots_array: row.party_slots_array,
      extra_parties_arr: extraParties[row.catalogue_id] || [],
      final_price: prices[row.catalogue_id] || row.suggested_price,
    }));
    if (!markings.length) { setAlert({ msg: 'No markings to save', type: 'warning' }); return; }
    setSaving(true);
    try {
      const r = await api.post('/marking/save', { markings, sale_no: saleNo });
      setAlert({ msg: `✅ ${r.data.saved} markings saved.${r.data.duplicates ? ` ${r.data.duplicates} duplicates skipped.` : ''}`, type: 'success' });
      setPreview([]);
    } catch (e) { setAlert({ msg: e.response?.data?.error || e.message, type: 'error' }); }
    finally { setSaving(false); }
  };

  const activeCount = preview.filter(r => !skipRows[r.catalogue_id]).length;

  // Build filter options from preview
  const allGradesOpts  = [...new Set(preview.map(r => r.grade).filter(Boolean))].sort();
  const allGardensOpts = [...new Set(preview.map(r => r.garden).filter(Boolean))].sort();
  const allBrokersOpts = [...new Set(preview.map(r => r.broker).filter(Boolean))].sort();

  // Apply filters
  const filteredPreview = preview.filter(row => {
    if (filterGrades.length  > 0 && !filterGrades.includes(row.grade))   return false;
    if (filterGardens.length > 0 && !filterGardens.includes(row.garden)) return false;
    if (filterBrokers.length > 0 && !filterBrokers.includes(row.broker)) return false;
    if (searchLot && !(row.lot_no || '').toLowerCase().includes(searchLot.toLowerCase())) return false;
    return true;
  });

  const hasFilters = filterGrades.length > 0 || filterGardens.length > 0 || filterBrokers.length > 0 || searchLot;
  const clearFilters = () => { setFilterGrades([]); setFilterGardens([]); setFilterBrokers([]); setSearchLot(''); };

  const fmtDate = (d) => {
    if (!d) return '—';
    try { const dt = new Date(d); return `${String(dt.getDate()).padStart(2,'0')}/${String(dt.getMonth()+1).padStart(2,'0')}`; }
    catch { return String(d).slice(0,5); }
  };

  const fmtRate = (row) => {
    const mn = row.min_deal_price, mx = row.max_deal_price;
    if (!mn && !mx) return '—';
    if (mn && mx && Math.abs(parseFloat(mn)-parseFloat(mx)) > 0.5)
      return `${Number(mn).toFixed(0)}-${Number(mx).toFixed(0)}`;
    return `${Number(mn||mx).toFixed(0)}/-`;
  };

  // Build compact slot display for a lot: always 5 slots, filled left-to-right, no gaps
  const getSlots = (row) => {
    const main  = row.party_slots_array || [];
    const extra = extraParties[row.catalogue_id] || [];
    const combined = [...main, ...extra].slice(0, MAX_SLOTS);
    // Pad to 5
    while (combined.length < MAX_SLOTS) combined.push(null);
    return combined;
  };

  return (
    <div>
      <h2 style={{ marginBottom: 4, color: '#1a3c5e' }}>✅ Create Markings</h2>
      <p style={{ color: '#888', fontSize: 13, marginBottom: 16 }}>
        Select parties. P1–P5 filled compactly — no gaps. Lot order matches original Excel file.
      </p>

      {alert && <Alert msg={alert.msg} type={alert.type} />}

      <div style={{ display: 'grid', gridTemplateColumns: '320px 1fr', gap: 16, marginBottom: 16 }}>
        {/* ── LEFT: Party list ── */}
        <Card style={{ padding: 14 }}>
          <div style={{ fontWeight: 700, fontSize: 14, color: '#1a3c5e', marginBottom: 10 }}>
            Select Parties <span style={{ fontWeight: 400, fontSize: 12, color: '#888' }}>(unlimited)</span>
          </div>
          <input value={partySearch} onChange={e => setPartySearch(e.target.value)} placeholder="Search…"
            style={{ width: '100%', padding: '7px 10px', border: '1.5px solid #e2e8f0', borderRadius: 6, fontSize: 13, marginBottom: 8 }} />
          <div style={{ display: 'flex', gap: 6, marginBottom: 8 }}>
            <Button size="sm" variant="outline" onClick={selectAll}   style={{ flex: 1, fontSize: 11 }}>✓ Select All</Button>
            <Button size="sm" variant="outline" onClick={deselectAll} style={{ flex: 1, fontSize: 11 }}>✕ Clear</Button>
          </div>
          <div style={{ maxHeight: 460, overflowY: 'auto', border: '1px solid #f0f4f8', borderRadius: 6 }}>
            {filteredParties.map(p => {
              const sel = !!selParties.find(x => x.id === p.id);
              const idx = selParties.findIndex(x => x.id === p.id);
              return (
                <div key={p.id} onClick={() => toggleParty(p)}
                  style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 10px', cursor: 'pointer',
                    background: sel ? '#dbeafe' : '#fff', borderBottom: '1px solid #f0f4f8', userSelect: 'none' }}>
                  <div style={{ width: 18, height: 18, borderRadius: 3,
                    border: `2px solid ${sel ? '#1a3c5e' : '#cbd5e0'}`,
                    background: sel ? '#1a3c5e' : '#fff',
                    display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                    {sel && <span style={{ color: '#fff', fontSize: 11, fontWeight: 700 }}>✓</span>}
                  </div>
                  <div style={{ flex: 1 }}>
                    <span style={{ fontWeight: 700, fontSize: 12, color: '#1a3c5e' }}>[{p.party_code}]</span>
                    <span style={{ fontSize: 12, marginLeft: 5 }}>{p.party_name}</span>
                  </div>
                  {sel && <span style={{ background: '#1a3c5e', color: '#fff', fontSize: 10, fontWeight: 700, padding: '1px 6px', borderRadius: 99 }}>P{idx+1}</span>}
                </div>
              );
            })}
          </div>
          {selParties.length > 0 && (
            <div style={{ marginTop: 8, fontSize: 11, color: '#1a3c5e', background: '#eff6ff', padding: '6px 10px', borderRadius: 6, lineHeight: 1.7 }}>
              <b>{selParties.length} selected:</b><br/>
              {selParties.map((p, i) => `P${i+1}:${p.party_code}`).join(' · ')}
            </div>
          )}
        </Card>

        {/* ── RIGHT: Sale selector ── */}
        <Card style={{ padding: 16, alignSelf: 'start' }}>
          <div style={{ fontWeight: 700, fontSize: 14, color: '#1a3c5e', marginBottom: 12 }}>Sale & Preview</div>
          <div style={{ display: 'flex', gap: 12, alignItems: 'flex-end', flexWrap: 'wrap' }}>
            <div>
              <label style={{ display: 'block', fontSize: 11, fontWeight: 700, color: '#555', marginBottom: 4, textTransform: 'uppercase', letterSpacing: 0.4 }}>Sale Number *</label>
              <select value={saleNo} onChange={e => setSaleNo(e.target.value)}
                style={{ padding: '8px 12px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13, minWidth: 200 }}>
                <option value="">Select sale…</option>
                {saleNos.map(s => <option key={s.sale_no} value={s.sale_no}>Sale {s.sale_no} ({s.lot_count} lots)</option>)}
              </select>
            </div>
            <Button onClick={runPreview} disabled={loading || !selParties.length || !saleNo} variant="primary">
              {loading ? '⏳ Fetching…' : '🔍 Preview Lots'}
            </Button>
            {preview.length > 0 && (
              <Button onClick={save} disabled={saving || activeCount === 0} variant="success">
                {saving ? 'Saving…' : `💾 Save ${activeCount} Markings`}
              </Button>
            )}
          </div>

          {preview.length > 0 && (
            <div style={{ marginTop: 10, fontSize: 12, color: '#555' }}>
              <b>{preview.length}</b> total ·{' '}
              <b style={{ color: '#1a7a4a' }}>{filteredPreview.length}</b> shown ·{' '}
              <b>{activeCount}</b> active
              {hasFilters && (
                <button onClick={clearFilters}
                  style={{ marginLeft: 12, fontSize: 11, color: '#c0392b', background: 'none', border: '1px solid #fecaca', borderRadius: 4, padding: '2px 8px', cursor: 'pointer' }}>
                  ✕ Clear filters
                </button>
              )}
            </div>
          )}

          <div style={{ marginTop: 10, padding: '8px 12px', background: '#f0fdf4', border: '1px solid #bbf7d0', borderRadius: 6, fontSize: 11, color: '#166534' }}>
            <b>P1–P5 logic:</b> Slots filled compactly — if a party is not eligible for a lot, the next eligible party moves up (no gaps).
            Add any party manually using the + column — type code and press Enter.
          </div>
        </Card>
      </div>

      {/* ── MARKING TABLE ── */}
      {preview.length > 0 && (
        <Card style={{ padding: 0, overflow: 'hidden' }}>
          <div style={{ padding: '10px 16px', background: '#1a3c5e', color: '#fff', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <div style={{ fontWeight: 700, fontSize: 14 }}>
              Marking List — Sale #{saleNo}
              {hasFilters && <span style={{ fontSize: 11, fontWeight: 400, marginLeft: 10, opacity: 0.8 }}>({filteredPreview.length} of {preview.length} shown)</span>}
            </div>
            <div style={{ fontSize: 12, opacity: 0.8 }}>{preview.length} lots · max {MAX_SLOTS} slots/lot</div>
          </div>

          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
              <thead>
                <tr style={{ background: '#234d78', color: '#fff' }}>
                  <th style={{ padding: '8px 6px', textAlign: 'center', fontWeight: 600, width: 40 }}>Skip</th>
                  {/* P1-P5 always fixed */}
                  {[1,2,3,4,5].map(n => (
                    <th key={n} style={{ padding: '8px 6px', textAlign: 'center', fontWeight: 600, background: '#1a3c5e', minWidth: 60 }}>P{n}</th>
                  ))}
                  {/* Filterable headers */}
                  <th style={{ padding: '8px 8px', textAlign: 'left', fontWeight: 600 }}>
                    <ColFilter label="Bro" options={allBrokersOpts} selected={filterBrokers} onChange={setFilterBrokers} />
                  </th>
                  <th style={{ padding: '8px 8px', textAlign: 'left', fontWeight: 600 }}>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                      <span>Lot</span>
                      <input value={searchLot} onChange={e => setSearchLot(e.target.value)}
                        onClick={e => e.stopPropagation()} placeholder="Search…"
                        style={{ width: 68, padding: '2px 5px', border: '1px solid rgba(255,255,255,0.3)', borderRadius: 4,
                          fontSize: 10, background: 'rgba(255,255,255,0.15)', color: '#fff', outline: 'none' }} />
                    </div>
                  </th>
                  <th style={{ padding: '8px 8px', textAlign: 'left', fontWeight: 600, minWidth: 140 }}>
                    <ColFilter label="Garden" options={allGardensOpts} selected={filterGardens} onChange={setFilterGardens} />
                  </th>
                  <th style={{ padding: '8px 8px', textAlign: 'left', fontWeight: 600 }}>
                    <ColFilter label="Grd" options={allGradesOpts} selected={filterGrades} onChange={setFilterGrades} />
                  </th>
                  <th style={{ padding: '8px 8px', textAlign: 'right', fontWeight: 600, minWidth: 100 }}>Rate (Min-Max)</th>
                  <th style={{ padding: '8px 8px', textAlign: 'right', fontWeight: 600 }}>Qty</th>
                  <th style={{ padding: '8px 8px', textAlign: 'right', fontWeight: 600 }}>NWt</th>
                  <th style={{ padding: '8px 8px', textAlign: 'center', fontWeight: 600 }}>GP Dt</th>
                  <th style={{ padding: '8px 8px', textAlign: 'left', fontWeight: 600, minWidth: 120 }}>+ Add Party</th>
                </tr>
              </thead>
              <tbody>
                {filteredPreview.length === 0 ? (
                  <tr>
                    <td colSpan={16} style={{ padding: 24, textAlign: 'center', color: '#aaa' }}>
                      No lots match current filters.{' '}
                      <button onClick={clearFilters} style={{ color: '#1a3c5e', background: 'none', border: 'none', cursor: 'pointer', textDecoration: 'underline', fontSize: 13 }}>Clear filters</button>
                    </td>
                  </tr>
                ) : filteredPreview.map((row, i) => {
                  const skip     = !!skipRows[row.catalogue_id];
                  const slots    = getSlots(row);
                  const inputVal = addInputs[row.catalogue_id] || '';
                  const sugg     = getCodeSuggestions(inputVal);
                  const notif    = notifications[row.catalogue_id];

                  return (
                    <React.Fragment key={row.catalogue_id}>
                      <tr style={{ borderBottom: notif ? 'none' : '1px solid #f0f4f8',
                        background: skip ? '#fff5f5' : (i % 2 === 0 ? '#fff' : '#fafbfc'),
                        opacity: skip ? 0.4 : 1 }}>
                        <td style={{ padding: '5px 6px', textAlign: 'center' }}>
                          <input type="checkbox" checked={skip}
                            onChange={() => setSkipRows(s => ({ ...s, [row.catalogue_id]: !s[row.catalogue_id] }))} />
                        </td>

                        {/* P1-P5 compact slots */}
                        {slots.map((slot, si) => (
                          <td key={si} style={{ padding: '5px 6px', textAlign: 'center' }}>
                            {slot
                              ? <span style={{ background: '#1a3c5e', color: '#fff', padding: '3px 8px', borderRadius: 99, fontSize: 11, fontWeight: 700, display: 'inline-block' }}>
                                  {slot.party_code}
                                </span>
                              : <span style={{ color: '#d1d5db', fontSize: 11 }}>—</span>
                            }
                          </td>
                        ))}

                        <td style={{ padding: '5px 8px', fontWeight: 600, color: '#555', whiteSpace: 'nowrap' }}>{row.broker}</td>
                        <td style={{ padding: '5px 8px', fontFamily: 'monospace', fontSize: 11, color: '#1a3c5e', fontWeight: 700 }}>{row.lot_no}</td>
                        <td style={{ padding: '5px 8px', fontWeight: 700, color: '#1a3c5e', maxWidth: 160, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }} title={row.garden}>{row.garden}</td>
                        <td style={{ padding: '5px 8px' }}>
                          <span style={{ background: '#dbeafe', color: '#1e40af', padding: '2px 7px', borderRadius: 99, fontSize: 11, fontWeight: 700 }}>{row.grade}</span>
                        </td>
                        <td style={{ padding: '5px 8px', textAlign: 'right', fontWeight: 600, color: '#1a3c5e', whiteSpace: 'nowrap' }}>{fmtRate(row)}</td>
                        <td style={{ padding: '5px 8px', textAlign: 'right', fontWeight: 600 }}>{row.bags || '—'}</td>
                        <td style={{ padding: '5px 8px', textAlign: 'right' }}>{row.net_wt || '—'}</td>
                        <td style={{ padding: '5px 8px', textAlign: 'center', fontSize: 11, color: '#888' }}>{fmtDate(row.gp_date)}</td>

                        {/* Add party — works by filling next available slot */}
                        <td style={{ padding: '5px 8px' }}>
                          <div style={{ position: 'relative', display: 'inline-block' }}>
                            <div style={{ display: 'flex', gap: 3, alignItems: 'center' }}>
                              <input
                                value={inputVal}
                                onChange={e => {
                                  setAddInputs(prev => ({ ...prev, [row.catalogue_id]: e.target.value.toUpperCase() }));
                                  setNotifications(prev => { const n = {...prev}; delete n[row.catalogue_id]; return n; });
                                }}
                                onKeyDown={e => handleAddKeyDown(e, row.catalogue_id)}
                                placeholder="Code"
                                maxLength={5}
                                title="Type party code + Enter to add"
                                style={{ width: 55, padding: '4px 6px', border: '1.5px solid #cbd5e0', borderRadius: 5,
                                  fontSize: 12, fontFamily: 'monospace', textTransform: 'uppercase',
                                  background: '#fff', color: '#1a2533' }}
                              />
                              <button
                                onClick={() => addExtraParty(row.catalogue_id)}
                                title="Add party (or press Enter)"
                                style={{ padding: '4px 8px', background: '#1a3c5e', color: '#fff', border: 'none',
                                  borderRadius: 5, cursor: 'pointer', fontSize: 12, fontWeight: 700, lineHeight: 1 }}>+</button>
                            </div>
                            {/* Autocomplete dropdown */}
                            {sugg.length > 0 && inputVal.length > 0 && (
                              <div style={{ position: 'absolute', top: '100%', left: 0, background: '#fff',
                                border: '1px solid #e2e8f0', borderRadius: 6, zIndex: 999,
                                boxShadow: '0 4px 12px rgba(0,0,0,0.1)', minWidth: 160 }}>
                                {sugg.map(s => (
                                  <div key={s.id}
                                    onMouseDown={e => {
                                      e.preventDefault();
                                      setAddInputs(prev => ({ ...prev, [row.catalogue_id]: s.party_code }));
                                      setTimeout(() => addExtraParty(row.catalogue_id), 80);
                                    }}
                                    style={{ padding: '7px 10px', cursor: 'pointer', fontSize: 12, borderBottom: '1px solid #f0f4f8', color: '#1a2533' }}
                                    onMouseEnter={e => e.currentTarget.style.background = '#f0f8ff'}
                                    onMouseLeave={e => e.currentTarget.style.background = '#fff'}>
                                    <b style={{ color: '#1a3c5e' }}>{s.party_code}</b> — {s.party_name}
                                  </div>
                                ))}
                              </div>
                            )}
                          </div>
                        </td>
                      </tr>
                      {/* Notification row for this lot */}
                      {notif && (
                        <tr>
                          <td colSpan={16} style={{ padding: '4px 16px', background: notif.type === 'error' ? '#fef2f2' : '#fffbeb', borderBottom: '1px solid #f0f4f8' }}>
                            <span style={{ fontSize: 11, color: notif.type === 'error' ? '#991b1b' : '#92400e', fontWeight: 600 }}>
                              {notif.msg}
                            </span>
                            <button onClick={() => setNotifications(prev => { const n={...prev}; delete n[row.catalogue_id]; return n; })}
                              style={{ marginLeft: 8, border: 'none', background: 'none', cursor: 'pointer', fontSize: 10, color: '#888' }}>✕</button>
                          </td>
                        </tr>
                      )}
                    </React.Fragment>
                  );
                })}
              </tbody>
            </table>
          </div>
        </Card>
      )}
    </div>
  );
}
